from .common import *
def style():
    mpl.rcParams.update({'font.family': 'sans-serif', 'font.sans-serif': ['DejaVu Sans', 'DejaVu Sans'], 'font.size': 8, 'axes.titlesize': 8.3, 'axes.labelsize': 8, 'xtick.labelsize': 7.5, 'ytick.labelsize': 7.5, 'legend.fontsize': 7.5, 'axes.spines.top': False, 'axes.spines.right': False, 'axes.linewidth': 0.65, 'xtick.major.width': 0.65, 'ytick.major.width': 0.65, 'pdf.fonttype': 42, 'ps.fonttype': 42, 'svg.fonttype': 'none', 'savefig.facecolor': 'white', 'savefig.dpi': 601})
def render():
 style()
 records=read_csv(DATA/'branches/fig9_rows.csv')
 env=dict(globals(),records=records)
 exec("processes = ['midRH', 'q700_storm_relative_horizontal_advection', 'q850_moisture_flux_convergence', 'shear200_500', 'PI_headroom']\nlabels = ['Midlevel relative humidity', '700-hPa storm-relative moisture advection', '850-hPa moisture-flux convergence', '200–500-hPa shear', 'PI headroom']\nunits = ['pp', 'g kg⁻¹ day⁻¹', 'g kg⁻¹ day⁻¹', 'm s⁻¹', 'm s⁻¹']\ncolors = {'raw': '#333333', 'screened': '#888888', 'adjusted': '#0072B2', 'slope': '#333333'}\nmarkers = {'raw': 'o', 'screened': 's', 'adjusted': 'D', 'slope': 'o'}\nplt.rcParams.update({'font.family': 'DejaVu Sans', 'font.size': 8, 'axes.labelsize': 8, 'axes.titlesize': 9, 'xtick.labelsize': 8, 'ytick.labelsize': 8, 'legend.fontsize': 8, 'axes.linewidth': 0.6, 'xtick.major.width': 0.6, 'ytick.major.width': 0.6, 'pdf.fonttype': 42, 'ps.fonttype': 42, 'svg.fonttype': 'none', 'savefig.dpi': 601})\nW, H = (180, 205)\nfig = plt.figure(figsize=(W / 25.4, H / 25.4))\n\ndef tx(x, y, t, **kw):\n    return fig.text(x / W, y / H, t, fontsize=8, **kw)\n\ndef new_ax(x, y, w, h, gid):\n    ax = fig.add_axes([x / W, y / H, w / W, h / H])\n    ax.set_gid(gid)\n    for spine in ['top', 'right', 'left']:\n        ax.spines[spine].set_visible(False)\n    ax.tick_params(axis='y', left=False, labelleft=False)\n    ax.tick_params(axis='x', length=2.5, pad=1.5)\n    ax.axvline(0, c='.75', lw=0.6, zorder=0)\n    ax.xaxis.set_major_locator(MaxNLocator(nbins=3))\n    ax.xaxis.set_major_formatter(FuncFormatter(lambda value, pos: f'{value:g}'))\n    ax.annotate(gid, xy=(0, 1), xycoords='axes fraction', xytext=(-15, 7), textcoords='offset points', fontsize=10, fontweight='bold', va='bottom', annotation_clip=False)\n    return ax\n\ndef point(ax, r, y):\n    e, lo, hi = (float(r[k]) for k in ['estimate', 'ci_low', 'ci_high'])\n    if np.isfinite(e):\n        color = colors[r.role]\n        marker = markers[r.role]\n        if np.isfinite(lo) and np.isfinite(hi):\n            assert lo <= e <= hi, (r.process, r.role)\n            ax.errorbar(e, y, xerr=[[e - lo], [hi - e]], fmt=marker, color=color, mfc='white' if r.role == 'screened' else color, ms=3.3, elinewidth=0.9, capsize=2, mew=0.8)\n        else:\n            ax.plot(e, y, marker=marker, color=color, ms=3.3)\n    else:\n        ax.text(0.5, y, 'Not estimated', transform=ax.get_yaxis_transform(), ha='center', va='center', color=colors['adjusted'], fontsize=8)\n\ndef count(r):\n    return 'NA' if not np.isfinite(r.n_sid) else f'{int(r.n_sid)}/{int(r.n_pairs)}'\ntx(12, 201, 'Environmental differences between post- and pre-peak intensity branches', fontweight='bold')\ntx(12, 196, 'Tpre: genesis → first LMI; Tpost: last LMI → termination')\ntx(12, 191, 'A = (Tpre − Tpost)/(Tpre + Tpost); A > 0 means a longer pre-LMI duration')\ntx(12, 184, 'Post − pre within the same 10-kt intensity bin', fontweight='bold')\ntx(115, 184, 'Branch-difference slope with A', fontweight='bold')\nhandles = [Line2D([0], [0], marker=markers[k], color=colors[k], mfc='white' if k == 'screened' else colors[k], ms=3.3, lw=0.8, label=l) for k, l in [('raw', 'Raw'), ('screened', 'Screened raw'), ('adjusted', 'Adjusted')]]\nfig.legend(handles=handles, loc='center left', bbox_to_anchor=(10 / W, 176 / H), ncol=3, frameon=False, handlelength=1.2, handletextpad=0.35, columnspacing=0.65, borderaxespad=0)\ntx(82, 176, 'SID/pairs', ha='center', va='center')\ntx(115, 176, 'Per 0.1 A; own analysis support', va='center')\naxes = []\nrow_groups = []\nfor j, (process, label, unit) in enumerate(zip(processes, labels, units)):\n    title_y = 167 - 32 * j\n    ay = title_y - 19.5\n    ah = 14.5\n    lp = chr(97 + 2 * j)\n    rp = chr(98 + 2 * j)\n    left = new_ax(12, ay, 55, ah, lp)\n    right = new_ax(115, ay, 55, ah, rp)\n    axes.extend([left, right])\n    row_groups.append([lp, rp])\n    tx(12, title_y, label)\n    one = records[records.process.eq(process)]\n    r = one[one.role.eq('slope')].iloc[0]\n    tx(115, title_y, 'n = ' + count(r))\n    left.set_ylim(-0.6, 2.6)\n    right.set_ylim(-0.6, 0.6)\n    for y, role in [(2, 'raw'), (1, 'screened'), (0, 'adjusted')]:\n        r = one[one.role.eq(role)].iloc[0]\n        point(left, r, y)\n        y_mm = ay + ah * (y + 0.6) / 3.2\n        tx(82, y_mm, count(r), ha='center', va='center')\n    r = one[one.role.eq('slope')].iloc[0]\n    point(right, r, 0)\n    for ax, selection in [(left, one[one.role.ne('slope')]), (right, one[one.role.eq('slope')])]:\n        bounds = np.r_[selection.ci_low.to_numpy(float), selection.ci_high.to_numpy(float), selection.estimate.to_numpy(float), 0.0]\n        bounds = bounds[np.isfinite(bounds)]\n        lower, upper = (bounds.min(), bounds.max())\n        margin = (upper - lower) * 0.11 or 1\n        ax.set_xlim(lower - margin, upper + margin)\n    left.set_xlabel(unit, labelpad=2, fontfamily='DejaVu Sans', fontsize=8)\n    right.set_xlabel(unit + ' per 0.1 A', labelpad=2, fontfamily='DejaVu Sans', fontsize=8)\ntx(12, 3.5, 'Raw/screened/slope bars: 95% SID intervals;\\nadjusted bars: conditional 2.5th–97.5th percentiles.')",env)
 export(env['fig'],'Fig8')

